window.gangs_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

// ── Полоска прогресса ─────────────────────────────────────────────
gangs_elements.lib.Gang_bar=class extends e{
  constructor(w,color){
    super();color=color||0x448844;
    const bg=new A();bg.beginFill(0x080e08,1);bg.drawRoundedRect(0,0,w,8,2);bg.endFill();
    this.fill=new A();this.fill.beginFill(color,1);this.fill.drawRoundedRect(0,0,w,8,2);this.fill.endFill();
    this.addChild(bg,this.fill);this[this.fill.name='fill']=this.fill;
  }
  setPercent(p){this.fill.scale.x=Math.max(0,Math.min(1,p));}
};

// ── Карточка банды ────────────────────────────────────────────────
gangs_elements.lib.Gang_card=class extends e{
  constructor(){
    super();
    this.bg_mc=new A();this._drawBg(false);this.addChild(this.bg_mc);
    // Эмблема банды
    this.emblem_bg=new A();this.emblem_bg.beginFill(0x0c1a0c,1);this.emblem_bg.lineStyle(2,0x2a4a2a);this.emblem_bg.drawRoundedRect(0,0,100,100,8);this.emblem_bg.endFill();
    const ei=new z('',{fontFamily:'Arial',fontSize:44,align:'center'});ei.anchor.set(0.5,0.5);ei.x=50;ei.y=50;
    const ew=new e();ew.x=10;ew.y=10;ew.addChild(this.emblem_bg,ei);
    this[ei.name='emblem_icon']=ei;this[ew.name='emblem']=ew;this.addChild(ew);
    // Название банды
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#d0e060',dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});nt.x=122;nt.y=10;
    this[nt.name='name_txt']=nt;
    // Идеология
    const it=new z('',{fontFamily:'Southbank LT',fontSize:12,fill:'#6a8a4a',fontStyle:'italic'});it.x=122;it.y=34;
    this[it.name='ideology_txt']=it;
    // Бонус
    const bt=new z('',{fontFamily:'Arial',fontSize:12,fill:'#a0c060',wordWrap:true,wordWrapWidth:430});bt.x=122;bt.y=54;
    this[bt.name='bonus_txt']=bt;
    // Участники
    const mt=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#5a7a4a'});mt.x=122;mt.y=80;
    this[mt.name='members_txt']=mt;
    // Уровень банды + прогресс
    const lvl=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#8aaa50'});lvl.x=10;lvl.y=122;
    this[lvl.name='level_txt']=lvl;
    const bar=new gangs_elements.lib.Gang_bar(540,0x448844);bar.x=10;bar.y=138;
    this[bar.name='level_bar']=bar;
    // Кнопка вступить
    const jbg=new A();jbg.beginFill(0x1a3a0a,1);jbg.lineStyle(1,0x3a7a1a);jbg.drawRoundedRect(0,0,130,36,4);jbg.endFill();
    const jt=new z('ВСТУПИТЬ',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#90d040',align:'center'});jt.anchor.set(0.5,0.5);jt.x=65;jt.y=18;
    const jb=new e();jb.addChild(jbg,jt);jb.x=430;jb.y=10;
    jb.interactive=true;jb.buttonMode=true;
    jb.on('mouseover',()=>jbg.tint=0xcceeaa);jb.on('mouseout',()=>jbg.tint=0xffffff);
    this[jb.name='butt_join']=jb;this[jt.name='join_txt']=jt;
    // Кнопка взнос (видна только если состоишь)
    const cbg2=new A();cbg2.beginFill(0x2a1a00,1);cbg2.lineStyle(1,0x7a5010);cbg2.drawRoundedRect(0,0,130,36,4);cbg2.endFill();
    const ct2=new z('ВЗНОС',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#e0a030',align:'center'});ct2.anchor.set(0.5,0.5);ct2.x=65;ct2.y=18;
    const cb2=new e();cb2.addChild(cbg2,ct2);cb2.x=430;cb2.y=54;cb2.visible=false;
    cb2.interactive=true;cb2.buttonMode=true;
    cb2.on('mouseover',()=>cbg2.tint=0xeeddaa);cb2.on('mouseout',()=>cbg2.tint=0xffffff);
    this[cb2.name='butt_donate']=cb2;
    // Бейдж «Состоишь»
    const mbg=new A();mbg.beginFill(0x204808,1);mbg.lineStyle(1,0x508020);mbg.drawRoundedRect(0,0,100,22,3);mbg.endFill();
    const mt2=new z('СОСТОИШЬ',{fontFamily:'Southbank LT',fontSize:9,fontWeight:'bold',fill:'#80d020',align:'center'});mt2.anchor.set(0.5,0.5);mt2.x=50;mt2.y=11;
    const mbw=new e();mbw.addChild(mbg,mt2);mbw.x=430;mbw.y=96;mbw.visible=false;
    this[mbw.name='badge_member']=mbw;
    this.addChild(nt,it,bt,mt,lvl,bar,jb,cb2,mbw);
  }
  _drawBg(member){
    this.bg_mc.clear();
    if(member){this.bg_mc.beginFill(0x0c1e06,0.97);this.bg_mc.lineStyle(2,0x3a7018,0.9);}
    else{this.bg_mc.beginFill(0x090f05,0.92);this.bg_mc.lineStyle(1,0x1a3010,0.7);}
    this.bg_mc.drawRoundedRect(0,0,574,154,6);this.bg_mc.endFill();
  }
  setMember(v){
    this._drawBg(v);
    this.badge_member.visible=v;
    this.butt_donate.visible=v;
    this.join_txt.text=v?'ПОКИНУТЬ':'ВСТУПИТЬ';
    const jbg=this.butt_join.children[0];
    if(v){jbg.clear();jbg.beginFill(0x3a1010,1);jbg.lineStyle(1,0x882222);jbg.drawRoundedRect(0,0,130,36,4);jbg.endFill();this.join_txt.style.fill='#e04040';}
    else{jbg.clear();jbg.beginFill(0x1a3a0a,1);jbg.lineStyle(1,0x3a7a1a);jbg.drawRoundedRect(0,0,130,36,4);jbg.endFill();this.join_txt.style.fill='#90d040';}
  }
};

// ── Главное окно Банд ─────────────────────────────────────────────
gangs_elements.lib.Gangs_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x050c03,0.97);wb.lineStyle(2,0x285018,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();
    this.addChild(wb);
    const hb=new A();hb.beginFill(0x081802,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x285018,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);
    this.addChild(hb,hl);
    const ttl=new z('БАНДЫ',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#b8d840',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});
    ttl.x=20;ttl.y=12;this.addChild(ttl);
    // Моя банда лейбл
    const ml=new z('Моя банда:',{fontFamily:'Southbank LT',fontSize:11,fill:'#4a6a3a'});ml.x=260;ml.y=16;this.addChild(ml);
    const mt=new z('—',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#a0c840'});mt.x=360;mt.y=13;
    this[mt.name='my_gang_txt']=mt;this.addChild(mt);
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;
    cl.interactive=true;cl.buttonMode=true;cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // Сетка карточек 2×3
    const grid=new e();grid.x=10;grid.y=50;
    for(let i=0;i<6;i++){
      const gc=new gangs_elements.lib.Gang_card();
      gc.x=(i%2)*(574+12);gc.y=Math.floor(i/2)*(154+8);
      grid['card_'+i]=gc;grid.addChild(gc);
    }
    this[grid.name='gang_grid']=grid;this.addChild(grid);
    // Подсказка
    const hint=new z('Состоять можно только в одной банде. Бонусы банды применяются к вашим характеристикам.',{fontFamily:'Arial',fontSize:11,fill:'#3a5028',fontStyle:'italic'});
    hint.x=20;hint.y=510;this.addChild(hint);
  }
};

// ── Root MovieClip ─────────────────────────────────────────────────
gangs_elements.lib.gangs_elements=class extends n{
  constructor(){
    super({duration:1,framerate:30});
    const b=new gangs_elements.lib.Gangs_win();
    this[b.name='gangs_win']=b;this.addChild(b);
  }
};
gangs_elements.stage=gangs_elements.lib.gangs_elements}};
